mapper.select:
select bt.id, bt.tenant_id, bt.username, bt.tenant_name, bt.tenant_short_name, bt.tenant_logo, bt.industry, bt.contact_person, bt.contact_phone, bt.contact_email, bt.expire_time, bt.status from bedrock_tenant bt where bt.is_deleted = 0
and bt.tenant_id = #{param.tenantId}
and bt.status = #{param.status}
and bt.contact_email = #{param.contactEmail}
and bt.contact_person like concat('%',#{param.contactPerson},'%')
and bt.contact_phone like concat('%',#{param.contactPhone},'%')
and bt.tenant_name like concat('%',#{param.tenantName},'%')
